instrumento":"ÓRGÃO","comum":"BR-22-3179 - JARDIM ITAPARICA","cidade":"ITAPEVI","cargo":"ORGANISTA","nivel":"CANDIDATO(A)","id":"ae9956db-b1e1-55d0-967f-344f8b6ab03d"},"source_row":8945},{"after":{"nome":"NYCOLLE LIMA DOS SANTOS (ORGANISTA)","instrumento":"ÓRGÃO","comum":"BR-22-0673 - VILA DOUTOR CARDOSO","cidade":"ITAPEVI","cargo":"SECRETÁRIA DA MÚSICA","nivel":"RJM","id":"d794590f-b19c-5c7a-b44a-ff0ced1f3ad4"},"source_row":8950},{"after":{"nome":"SANDRA  COELHO DE AZEVEDO GOMES (INSTRUTORA)","instrumento":"ÓRGÃO","comum":"BR-22-0673 - VILA DOUTOR CARDOSO","cidade":"ITAPEVI","cargo":"ORGANISTA","nivel":"OFICIALIZADO(A)","id":"f234d05e-f941-51ad-bd84-7d8c057b3983"},"source_row":9135},{"after":{"nome":"SUZE FERREIRA MARTINS","instrumento":"ÓRGÃO","comum":"BR-22-3756 - MONTE SERRAT II","cidade":"ITAPEVI","cargo":"ORGANISTA","nivel":"OFICIALIZADO(A)","id":"06e617e1-ac75-51c3-a885-5e3df4f350e7"},"source_row":9264},{"after":{"nome":"TAIANA DOS SANTOS SANTESSO","instrumento":"ÓRGÃO","comum":"BR-22-1252 - JARDIM ISAURA","cidade":"SANTANA DE PARNAÍBA","cargo":"ORGANISTA","nivel":"RJM","id":"8d5c78de-bc89-55c0-827e-f03db0e83426"},"source_row":9267},{"after":{"nome":"TAINÁ SANTOS DA CRUZ","instrumento":"ÓRGÃO","comum":"BR-22-0672 - JARDIM SOROCABANA","cidade":"ITAPEVI","cargo":"ORGANISTA","nivel":"OFICIALIZADO(A)","id":"70fea561-eb07-5707-a3df-81c14c621d67"},"source_row":9271},{"after":{"nome":"VANESSA SILVA DO NASCIMENTO EVANGELISTA","instrumento":"ÓRGÃO","comum":"BR-22-1251 - SANTANA DE PARNAÍBA - CENTRAL","cidade":"SANTANA DE PARNAÍBA","cargo":"ORGANISTA","nivel":"OFICIALIZADO(A)","id":"9d0e8680-e76e-54df-856d-b5c125292809"},"source_row":9345},{"after":{"nome":"YASMIN DE OLIVEIRA MATOS","instrumento":"ÓRGÃO","comum":"BR-21-1565 - PARQUE LARANJEIRAS II","cidade":"PIRAPORA DO BOM JESUS","cargo":"ORGANISTA","nivel":"RJM / ENSAIO","id":"b8712ee1-19c4-5c44-8767-26edf8eb836e"},"source_row":9396}]}$sam_data$::jsonb;
 item jsonb;
 target jsonb;
 affected integer;
 updated integer := 0;
 inserted integer := 0;
 unchanged integer := 0;
BEGIN
 IF NOT pg_try_advisory_xact_lock(20261112, 9404) THEN
  RAISE EXCEPTION 'Outra importacao SAM esta em andamento';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(payload->'updates') LOOP
  target := item->'after';
  IF target->>'nome' = 'LINDAURA' OR upper(target->>'comum') LIKE '%BARBACENA%' THEN
   RAISE EXCEPTION 'Registro excluido encontrado no lote';
  END IF;
  UPDATE public.cadastro AS c SET
   nome = target->>'nome', instrumento = target->>'instrumento',
   comum = target->>'comum', cidade = target->>'cidade',
   cargo = target->>'cargo', nivel = target->>'nivel'
  WHERE c.id = (item->>'id')::uuid AND to_jsonb(c) = item->'before';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected = 0 THEN
   IF NOT EXISTS (SELECT 1 FROM public.cadastro c WHERE c.id = (item->>'id')::uuid AND to_jsonb(c) = target) THEN
    RAISE EXCEPTION 'Cadastro alterado desde a conciliacao ou acesso sem UPDATE: %', item->>'id';
   END IF;
   unchanged := unchanged + 1;
  ELSE updated := updated + affected;
  END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(payload->'inserts') LOOP
  target := item->'after';
  IF target->>'nome' = 'LINDAURA' OR upper(target->>'comum') LIKE '%BARBACENA%' THEN
   RAISE EXCEPTION 'Registro excluido encontrado no lote';
  END IF;
  IF EXISTS (SELECT 1 FROM public.cadastro c WHERE c.id = (target->>'id')::uuid) THEN
   IF NOT EXISTS (SELECT 1 FROM public.cadastro c WHERE c.id = (target->>'id')::uuid AND to_jsonb(c) = target) THEN
    RAISE EXCEPTION 'Conflito de ID em inclusao: %',target->>'id';
   END IF;
   unchanged := unchanged + 1;
  ELSE
   IF EXISTS (
    SELECT 1 FROM public.cadastro c WHERE
     btrim(regexp_replace(translate(upper(c.nome),'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ','AAAAAEEEEIIIIOOOOOUUUUC'),'[^A-Z0-9]+',' ','g')) =
     btrim(regexp_replace(translate(upper(target->>'nome'),'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ','AAAAAEEEEIIIIOOOOOUUUUC'),'[^A-Z0-9]+',' ','g'))
   ) THEN RAISE EXCEPTION 'Nome apareceu desde a conciliacao: %',target->>'nome'; END IF;
   INSERT INTO public.cadastro(id,nome,instrumento,comum,cidade,cargo,nivel)
    VALUES ((target->>'id')::uuid,target->>'nome',target->>'instrumento',target->>'comum',target->>'cidade',target->>'cargo',target->>'nivel');
   inserted := inserted + 1;
  END IF;
 END LOOP;
 FOR target IN
  SELECT value->'after' FROM jsonb_array_elements(payload->'updates')
  UNION ALL SELECT value->'after' FROM jsonb_array_elements(payload->'inserts')
 LOOP
  IF NOT EXISTS (SELECT 1 FROM public.cadastro c WHERE c.id=(target->>'id')::uuid AND to_jsonb(c)=target) THEN
   RAISE EXCEPTION 'Conferencia final falhou: %',target->>'id';
  END IF;
 END LOOP;
 RAISE NOTICE 'Conferido: % atualizados, % incluidos, % ja aplicados. 18 pendencias fora do lote.',updated,inserted,unchanged;
END;
$sam_import$;
COMMIT;
